// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for ru-apiz-prob: M8 gate, shells stored via free API
// Flo: mock site + mock vendor > ladder fetch of shell pages > assert $0, kinds, caps, robots, climb
// I/O: mock responses > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const ladd = @import("ru-tier-ladd.zig"); const apiz = @import("ru-apiz-prob.zig"); const inde = @import("st-page-inde.zig"); const pipe = @import("ru-page-fetc.zig"); const vmock = @import("nt-vend-mock.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Rig = struct { tmpz: std.testing.TmpDir, srv: mock.Mock, vmk: vmock.Mock, dirz: []u8, dbzz: sqli.Db, aren: std.heap.ArenaAllocator, lad: ladd.Ladd,
pub fn up(self: *Rig, conf: cfgz.Conf) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); try self.srv.start(std.testing.io); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.vmk = vmock.Mock.init(allo); self.lad = .{ .gpaz = allo, .iozz = std.testing.io, .conf = conf, .dbzz = &self.dbzz, .dirz = self.dirz, .back = self.vmk.backend(), .priv = true }; }
pub fn down(self: *Rig) void { self.vmk.deinit(); self.aren.deinit(); self.dbzz.close(); self.srv.halt(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn go(self: *Rig, path: []const u8) !pipe.Outc { var buf: [64]u8 = undefined; return ladd.laddFetc(&self.lad, self.aren.allocator(), self.srv.urlOf(&buf, path)); }
pub fn reco(self: *Rig, path: []const u8) !?inde.Reco { var buf: [64]u8 = undefined; return inde.recoGet(&self.dbzz, self.aren.allocator(), self.srv.urlOf(&buf, path)); } };
fn rich() cfgz.Conf { var conf: cfgz.Conf = .{}; conf.vend_free_cred = .{ .deco = 100, .zenr = 100, .brig = 100 }; return conf; }
fn free0(rig: *Rig, out: pipe.Outc) !void { try std.testing.expectEqualStrings("new", out.stat); try std.testing.expectEqual(@as(i64, 1), out.tier); try std.testing.expectEqual(@as(u32, 0), out.cred); try std.testing.expectEqual(@as(u64, 0), out.micr); try std.testing.expectEqual(@as(usize, 0), rig.vmk.calls.items.len); }
test "spa shell: /api/ string found in the script, stored as json at $0" { var rig: Rig = undefined; try rig.up(rich()); defer rig.down(); const out = try rig.go("/spa"); try free0(&rig, out); try std.testing.expectEqualStrings("json", out.kind); const rec = (try rig.reco("/spa")).?; try std.testing.expectEqualStrings("json", rec.kind); try std.testing.expect(std.mem.indexOf(u8, rec.body, "Acme Widgets Alpha") != null); }
test "wordpress shell: api.w.org link leads to wp-json posts at $0" { var rig: Rig = undefined; try rig.up(rich()); defer rig.down(); const out = try rig.go("/wpjson"); try free0(&rig, out); try std.testing.expectEqualStrings("json", out.kind); }
test "next shell: buildId data URL at $0" { var rig: Rig = undefined; try rig.up(rich()); defer rig.down(); const out = try rig.go("/nextdata"); try free0(&rig, out); try std.testing.expectEqualStrings("json", out.kind); const rec = (try rig.reco("/nextdata")).?; try std.testing.expect(std.mem.indexOf(u8, rec.body, "Next Gizmos list") != null); }
test "iframe shell: the frame page is stored under the host URL at $0" { var rig: Rig = undefined; try rig.up(rich()); defer rig.down(); const out = try rig.go("/iframe"); try free0(&rig, out); try std.testing.expectEqualStrings("text", out.kind); const rec = (try rig.reco("/iframe")).?; try std.testing.expect(std.mem.indexOf(u8, rec.body, "Frame content sentence") != null); }
test "shell with no json anywhere still climbs, straight to render (plain skipped)" { var rig: Rig = undefined; try rig.up(rich()); defer rig.down(); const out = try rig.go("/spanone"); try std.testing.expectEqual(@as(i64, 3), out.tier); try std.testing.expectEqual(@as(usize, 1), rig.vmk.calls.items.len); try std.testing.expect(rig.vmk.calls.items[0].mode == .rend); }
test "robots-disallowed probe is never sent: ladder climbs instead" { var rig: Rig = undefined; try rig.up(rich()); defer rig.down(); const out = try rig.go("/spapriv"); try std.testing.expect(out.tier >= 3); try std.testing.expect(!std.mem.eql(u8, out.kind, "json")); try std.testing.expectEqual(@as(usize, 1), rig.vmk.calls.items.len); }
test "valid JSON that shares no words with the page is rejected, ladder climbs" { var rig: Rig = undefined; try rig.up(rich()); defer rig.down(); const out = try rig.go("/spaoff"); try std.testing.expect(out.tier >= 3); try std.testing.expect(!std.mem.eql(u8, out.kind, "json")); }
test "probe requests are capped by apiz_prob_maxz" { var conf = rich(); conf.apiz_prob_maxz = 3; var rig: Rig = undefined; try rig.up(conf); defer rig.down(); const out = try rig.go("/spamany"); try std.testing.expect(out.tier >= 3); try std.testing.expect(rig.srv.hits.load(.monotonic) <= 1 + 1 + 3); }
test "apiz_prob_enab=false skips probing entirely" { var conf = rich(); conf.apiz_prob_enab = false; var rig: Rig = undefined; try rig.up(conf); defer rig.down(); const out = try rig.go("/spa"); try std.testing.expect(out.tier >= 3); try std.testing.expectEqual(@as(u32, 1), rig.srv.hits.load(.monotonic)); }
test "winning kind is cached per host" { var rig: Rig = undefined; try rig.up(rich()); defer rig.down(); _ = try rig.go("/spa"); const kind = (try apiz.apizGet(&rig.dbzz, rig.aren.allocator(), "127.0.0.1")).?; try std.testing.expectEqualStrings("scri", kind); }
test "a vendor render is not sent when the free API works (no spend recorded)" { var rig: Rig = undefined; try rig.up(.{}); defer rig.down(); const out = try rig.go("/spa"); try std.testing.expectEqual(@as(i64, 1), out.tier); try std.testing.expectEqualStrings("json", out.kind); }
